import {FOOD_LIMITS,SOURCE_CAPACITY_LIMITS,GENERAL_FOOD_LIMITS} from './food-settings.js';
import {foodProduction} from './environment-settings.js';
import {DT} from './action-timing.js';
import {v,p,a,table,details} from './guide-markup.js';

/** Учебные группы, а не параметры мира. Сумму считает рабочая функция. */
export function guideProductionExample(){
 const groups=[{sources:[{},{}],period:10},{sources:[{}],period:20}];
 return {groups,production:foodProduction({individualFood:true,foodIslands:groups})};
}
const example=guideProductionExample();
export const GUIDE_FOOD_SOURCES_TEXT={
 'guide-food-sources':
 '<h4>Источники: производство и лежащий запас</h4>'
 +p('Источник — клетка суши, способная пополнять пищу. Островок — группа таких клеток с общим расписанием; одиночный куст — самостоятельная группа из одного источника. Житель видит источник в своём обзоре даже тогда, когда на нём нет готовой пищи. Само расписание, центры групп и параметры генерации ему не сообщаются.')
 +table('Поля пищевых условий',['Параметр','Что задаёт','Что важно при чтении'],[
 ['Число источников','Общий бюджет производящих клеток.','Это не число порций и не число островков. Максимум '+v(FOOD_LIMITS.sourcesMax,'клеток')+'.'],
 ['Число островков','На сколько основных групп распределить бюджет.','Остальная часть может стать одиночными кустами; большой запрос ограничивается числом источников.'],
 ['Период восстановления','Центр распределения периодов групп, в Т.','У разных групп сроки различаются. Это не синхронное пополнение всей карты.'],
 ['Разброс периодов','Относительную ширину случайных отклонений периодов.','Округление и границы могут менять итоговое среднее.'],
 ['Разброс размеров','Относительные случайные веса основных групп.','После целочисленного распределения бюджет сохраняется; проценты не являются строгими границами размеров каждого островка.'],
 ['Средняя вместимость и её разброс','Диапазон целых ёмкостей источников.','Границы вычисляются из среднего и процента, округляются и ограничиваются диапазоном '+v(SOURCE_CAPACITY_LIMITS.min)+'…'+v(SOURCE_CAPACITY_LIMITS.max,'порций')+'.']])
 +p('При создании нового мира источники получают начальный запас до своей вместимости. В дальнейшем пополнение ограничено этой вместимостью: когда подходит срок группы, каждый неполный источник получает порцию. Полный пропускает событие, и пропущенные порции не накапливаются в долг.')
 +'<h4>Пример: выработка не равна наличной пище</h4>'
 +table('Учебные группы с разными периодами',['Группа','Источников','Период'],example.groups.map((g,i)=>['Группа '+(i+1),v(g.sources.length),v(g.period,'Т')]))
 +p(`Их потенциальная выработка равна ${v(example.production,'порции/Т')}: складываются число источников, делённое на период каждой группы. Это средняя способность производить пищу, а не гарантия выдачи такого количества на каждом Т. Пополнения дискретны, а полные клетки не принимают очередную порцию. Чтобы узнать реальный запас, нужно смотреть пищу, лежащую на карте.`)
 +details('Размещение, размеры и сроки',
 p(`Бюджет распределяется между основными островками и одиночными кустами. Ориентир для кустов — ${v(FOOD_LIMITS.scatteredFraction*100,'%')} источников, но при большом числе запрошенных островков приоритет отдаётся непустым островкам. Нулевое число островков в расширенном режиме оставляет только отдельные кусты.`)
 +p('Центры основных групп разнесены по суше. Для группы выбираются ближайшие свободные клетки, а центры следующих групп заранее резервируются. Веса размеров нормируются, затем целые остатки распределяются так, чтобы общее число источников не изменилось. На карту не добавляются источники специально возле текущих жителей.')
 +p(`В обычном целочисленном режиме период каждой группы округляется и ограничивается диапазоном ${v(FOOD_LIMITS.intervalMin)}…${v(FOOD_LIMITS.individualIntervalMax,'Т')}. Расширенный ввод допускает центральный период от ${v(GENERAL_FOOD_LIMITS.intervalMin)} до ${v(GENERAL_FOOD_LIMITS.intervalMax,'Т')}; при дробном центре или выходе за обычный диапазон расписание строится по сетке ${v(DT,'Т')}. Разброс может расширять индивидуальные периоды, поэтому центр и край распределения — разные величины.`)
 +p('Начальная фаза сдвигает первое пополнение группы. Поэтому одинаковые периоды не означают одинаковые моменты урожая. После пополнения следующий срок переносится на период вперёд. При обычном расчёте мир проходит все подшаги, а не компенсирует пропущенные урожаи одним большим скачком.'))
 +details('Новый мир, ручное вмешательство и seed',
 p('Стартовые условия и поля плана опыта задают будущие миры. Панель изменения текущего мира применяется к уже существующей истории: жители, их память и геномы сохраняются. Изменение полей без применения ещё не меняет мир.')
 +p('Ручное вмешательство меняет производство, сохраняя пищу на каждой клетке. Если источник перенесли, старый запас остаётся на старом месте; на новом не создаётся дополнительная готовая еда. Уменьшение вместимости не удаляет избыток. При уменьшении/изменении групп раскладка может перестроиться; один только период можно изменить без переноса.')
 +p(`Новый календарь ручного вмешательства отсчитывается от его применения. Оставшаяся подготовка автоматики отменяется. При включённой ${a('environment','автоматике')} пищевые поля показывают фактические текущие условия и заблокированы; для ручного применения её нужно выключить.`)
 +p('Генерация пищи использует отдельные потоки случайности. При той же карте, профиле, seed и настройках начальная раскладка воспроизводима; смена пищевых настроек не сдвигает случайность геномов и размещения основателей. Разные пищевые настройки не обещают одинаковые островки. После начала опыта потребление жителей также меняет фактический запас.'))
 +p(`Связанные темы: ${a('geography','карта и обзор')}, ${a('deposits','пища без источника')}, ${a('environment','автоматические изменения')}, ${a('research','показатели населения и ресурсов')}.`),
};
